create extension if not exists pgcrypto;
create table if not exists projects (id uuid primary key default gen_random_uuid(), name text not null, description text, status text not null default 'planning', progress int not null default 0 check(progress between 0 and 100), created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists tasks (id uuid primary key default gen_random_uuid(), project_id uuid references projects(id) on delete cascade, title text not null, description text, agent text not null default 'NOVA', priority text not null default 'medium', status text not null default 'todo', result text, due_at timestamptz, created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists approvals (id uuid primary key default gen_random_uuid(), task_id uuid references tasks(id) on delete cascade, title text not null, payload jsonb default '{}'::jsonb, status text not null default 'pending', decided_at timestamptz, created_at timestamptz default now());
create table if not exists activities (id bigint generated always as identity primary key, project_id uuid references projects(id) on delete set null, agent text, event text not null, detail text, created_at timestamptz default now());
create table if not exists usage_logs (id bigint generated always as identity primary key, project_id uuid references projects(id) on delete set null, agent text not null, provider text not null, model text, input_tokens int default 0, output_tokens int default 0, total_tokens int default 0, latency_ms int default 0, estimated_cost_usd numeric(12,6), created_at timestamptz default now());
create table if not exists memories (id uuid primary key default gen_random_uuid(), project_id uuid references projects(id) on delete cascade, agent text, key text not null, content text not null, created_at timestamptz default now(), updated_at timestamptz default now());
create index if not exists idx_tasks_project on tasks(project_id); create index if not exists idx_tasks_status on tasks(status); create index if not exists idx_usage_created on usage_logs(created_at desc); create index if not exists idx_activity_created on activities(created_at desc);
-- V2 is intended as a private single-owner app. Keep service-role key server-side only.
